-- Issues Elysium owes a provider: an item a changeset asked to have its own issue, filed in a
-- tracker the watcher has not reached yet. Owed in the same transaction as the change that owes
-- it and landed by the watcher, like action_item_link_writes, so a crash between the two never
-- loses one. Landing it links the new issue to its item and deletes the row. See
-- docs/action-items.md.
--
-- A filing goes through exactly one credential of its provider, as a link does; deleting the
-- credential deletes what it still owed.

CREATE TABLE action_item_issue_filings (
    -- Generated by the API (UUIDv7), so ids order filings the way they were owed.
    id UUID PRIMARY KEY,
    -- An item is filed once at a time.
    action_item_id UUID NOT NULL UNIQUE REFERENCES action_items (id) ON DELETE CASCADE,
    provider link_provider NOT NULL,
    jira_credential_id UUID REFERENCES jira_credentials (id) ON DELETE CASCADE,
    github_credential_id UUID REFERENCES github_credentials (id) ON DELETE CASCADE,
    token_account_id UUID REFERENCES token_accounts (id) ON DELETE CASCADE,
    -- Where the issue opens, named as its provider names it: a Jira project key, a GitHub
    -- owner/name, or a YouTrack project's short name.
    destination TEXT NOT NULL,
    -- Who proposed it, as a changeset names its proposer; the link it lands as is theirs.
    filed_by TEXT NOT NULL,
    -- The changeset operation that owed it, so an undo finds it.
    changeset_operation_id UUID REFERENCES changeset_operations (id) ON DELETE SET NULL,
    -- The timeline record of the write, which links to the issue once it is filed.
    timeline_record_id UUID REFERENCES timeline_records (id) ON DELETE SET NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    -- When the first attempt began. An attempt cut short may have opened the issue before its
    -- answer was lost, so every later one looks for an issue opened since then first.
    first_attempt_at TIMESTAMPTZ,
    -- The provider's last answer, or why the filing waits.
    last_error TEXT,
    last_attempt_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT action_item_issue_filings_credential CHECK (
        (provider::text = 'jira' AND jira_credential_id IS NOT NULL
            AND github_credential_id IS NULL AND token_account_id IS NULL)
        OR (provider::text = 'github' AND github_credential_id IS NOT NULL
            AND jira_credential_id IS NULL AND token_account_id IS NULL)
        OR (provider::text = 'youtrack' AND token_account_id IS NOT NULL
            AND jira_credential_id IS NULL AND github_credential_id IS NULL)
    ),
    CONSTRAINT action_item_issue_filings_destination_length
        CHECK (char_length(destination) BETWEEN 1 AND 300),
    CONSTRAINT action_item_issue_filings_filed_by_shape
        CHECK (filed_by ~ '^(elysia|session:[0-9]+|project_manager:[0-9a-f-]{36})$'),
    CONSTRAINT action_item_issue_filings_attempts CHECK (attempts >= 0),
    CONSTRAINT action_item_issue_filings_last_error_length CHECK (char_length(last_error) <= 2000)
);

CREATE INDEX action_item_issue_filings_changeset_operation_id_idx
    ON action_item_issue_filings (changeset_operation_id)
    WHERE changeset_operation_id IS NOT NULL;
